// Captured with the pre-migration installed Mix datetime builtins.
use datetime::{DateTime, Utc};
#[test]
fn strftime_golden_corpus() {
    let pattern = "%Y|%C|%y|%m|%b|%B|%h|%d|%e|%a|%A|%w|%u|%U|%W|%V|%G|%g|%j|%D|%x|%F|%v|%H|%k|%I|%l|%P|%p|%M|%S|%f|%.f|%.3f|%.6f|%.9f|%R|%T|%X|%r|%c|%Z|%z|%:z|%::z|%:::z|%+|%s|%q|%%";
    assert_eq!(DateTime::<Utc>::from_timestamp(-62167219201, 0).unwrap().format(pattern).to_string(), "-0001|I5|99|12|Dec|December|Dec|31|31|Fri|Friday|5|5|52|52|52|-0001|99|365|12/31/99|12/31/99|-0001-12-31|31-Dec--0001|23|23|11|11|pm|PM|59|59|000000000||.000|.000000|.000000000|23:59|23:59:59|23:59:59|11:59:59 PM|Fri Dec 31 23:59:59 -0001|UTC|+0000|+00:00|+00:00:00|+00|-0001-12-31T23:59:59+00:00|-62167219201|4|%", "epoch -62167219201");
    assert_eq!(DateTime::<Utc>::from_timestamp(-62167219200, 0).unwrap().format(pattern).to_string(), "0000|00|00|01|Jan|January|Jan|01| 1|Sat|Saturday|6|6|00|00|52|-0001|99|001|01/01/00|01/01/00|0000-01-01| 1-Jan-0000|00| 0|12|12|am|AM|00|00|000000000||.000|.000000|.000000000|00:00|00:00:00|00:00:00|12:00:00 AM|Sat Jan  1 00:00:00 0000|UTC|+0000|+00:00|+00:00:00|+00|0000-01-01T00:00:00+00:00|-62167219200|1|%", "epoch -62167219200");
    assert_eq!(DateTime::<Utc>::from_timestamp(-1, 0).unwrap().format(pattern).to_string(), "1969|19|69|12|Dec|December|Dec|31|31|Wed|Wednesday|3|3|52|52|01|1970|70|365|12/31/69|12/31/69|1969-12-31|31-Dec-1969|23|23|11|11|pm|PM|59|59|000000000||.000|.000000|.000000000|23:59|23:59:59|23:59:59|11:59:59 PM|Wed Dec 31 23:59:59 1969|UTC|+0000|+00:00|+00:00:00|+00|1969-12-31T23:59:59+00:00|-1|4|%", "epoch -1");
    assert_eq!(DateTime::<Utc>::from_timestamp(0, 0).unwrap().format(pattern).to_string(), "1970|19|70|01|Jan|January|Jan|01| 1|Thu|Thursday|4|4|00|00|01|1970|70|001|01/01/70|01/01/70|1970-01-01| 1-Jan-1970|00| 0|12|12|am|AM|00|00|000000000||.000|.000000|.000000000|00:00|00:00:00|00:00:00|12:00:00 AM|Thu Jan  1 00:00:00 1970|UTC|+0000|+00:00|+00:00:00|+00|1970-01-01T00:00:00+00:00|0|1|%", "epoch 0");
    assert_eq!(DateTime::<Utc>::from_timestamp(1609459200, 0).unwrap().format(pattern).to_string(), "2021|20|21|01|Jan|January|Jan|01| 1|Fri|Friday|5|5|00|00|53|2020|20|001|01/01/21|01/01/21|2021-01-01| 1-Jan-2021|00| 0|12|12|am|AM|00|00|000000000||.000|.000000|.000000000|00:00|00:00:00|00:00:00|12:00:00 AM|Fri Jan  1 00:00:00 2021|UTC|+0000|+00:00|+00:00:00|+00|2021-01-01T00:00:00+00:00|1609459200|1|%", "epoch 1609459200");
    assert_eq!(DateTime::<Utc>::from_timestamp(1700000000, 0).unwrap().format(pattern).to_string(), "2023|20|23|11|Nov|November|Nov|14|14|Tue|Tuesday|2|2|46|46|46|2023|23|318|11/14/23|11/14/23|2023-11-14|14-Nov-2023|22|22|10|10|pm|PM|13|20|000000000||.000|.000000|.000000000|22:13|22:13:20|22:13:20|10:13:20 PM|Tue Nov 14 22:13:20 2023|UTC|+0000|+00:00|+00:00:00|+00|2023-11-14T22:13:20+00:00|1700000000|4|%", "epoch 1700000000");
    assert_eq!(DateTime::<Utc>::from_timestamp(253402300800, 0).unwrap().format(pattern).to_string(), "+10000|:0|00|01|Jan|January|Jan|01| 1|Sat|Saturday|6|6|00|00|52|9999|99|001|01/01/00|01/01/00|+10000-01-01| 1-Jan-+10000|00| 0|12|12|am|AM|00|00|000000000||.000|.000000|.000000000|00:00|00:00:00|00:00:00|12:00:00 AM|Sat Jan  1 00:00:00 +10000|UTC|+0000|+00:00|+00:00:00|+00|+10000-01-01T00:00:00+00:00|253402300800|1|%", "epoch 253402300800");
}
